function ensureg(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);echo 'PASS '.$label.PHP_EOL;}
try{
 $settings=sfc_defaults();ensureg(!$settings['genre_filter_enabled']&&count($settings['allowed_genres'])===count(sfc_genres())&&!$settings['extra_charts'],'All genres available; new rankings opt-in');
