 $snapshot=['items'=>[['rank'=>1,'genres'=>['Hip-Hop/Rap']],['rank'=>2,'genres'=>[]],['rank'=>3,'genres'=>['Pop']],['rank'=>4,'genres'=>['Pop','Hip-Hop/Rap']],['rank'=>5,'genres'=>['Latin Pop']],['rank'=>6,'genres'=>['Música Mexicana']]]];$settings['tracks_per_chart']=3;
