 $bad=false;try{sf_external_chart_normalize('deezer','rock',['data'=>[['id'=>123,'title'=>'Song','artist'=>['name'=>'Artist'],'position'=>4,'link'=>'https://www.deezer.com/track/123']]]);}catch(Throwable $e){$bad=true;}ensureg($bad,'Deezer missing positions rejected');
 $modern=sfc_defaults()+['genre_options_version'=>'1'];$modern['extra_charts']=['billboard_latin_pop','deezer_pop'];$modern['max_charts']=10;$modern['genre_filter_enabled']=true;$modern['allowed_genres']=['pop','latin_pop'];$saved=sfc_save_settings($modern);ensureg($saved['extra_charts']===$modern['extra_charts']&&$saved['allowed_genres']===['pop','latin_pop'],'Explicit source and genre settings saved');$legacy=$saved;unset($legacy['genre_options_version'],$legacy['extra_charts'],$legacy['allowed_genres'],$legacy['genre_filter_enabled']);$saved=sfc_save_settings($legacy);ensureg($saved['genre_filter_enabled']&&count($saved['extra_charts'])===2,'Older open settings form preserves new options');
 $db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);sfc_schema($db);$db->prepare('INSERT INTO sf_music_charts(chart_key,provider,market,title,enabled) VALUES(?,?,?,?,1)')->execute(['apple_mx','apple','mx','Fixture']);$db->prepare('INSERT INTO sf_chart_audio(identity,data,state,updated_at) VALUES(?,?,?,?)')->execute(['unknown','{}','ready',gmdate('c')]);$db->prepare('INSERT INTO sf_chart_entries VALUES(?,?,?,?)')->execute(['apple_mx',1,'unknown',json_encode(['title'=>'Song','artist'=>'Artist','genre_review'=>true])]);ensureg(sfc_entry_rows($db,'apple_mx')[0]['state']==='genre_review','Local genre review does not override shared audio ledger');
