 foreach([['approved','approved-job'],['running','running-job']] as [$identity,$job])$db->prepare('INSERT INTO sf_chart_audio(identity,data,state,job_id,updated_at) VALUES(?,?,?,?,?)')->execute([$identity,'{}','queued',$job,gmdate('c')]);$db->prepare('INSERT INTO sf_chart_entries VALUES(?,?,?,?)')->execute(['apple_mx',2,'approved','{}']);sfc_cancel_unselected($db);
 ensureg($db->query("SELECT state FROM sf_processing_jobs WHERE id='unknown-job'")->fetchColumn()==='cancelled'&&$db->query("SELECT state FROM sf_chart_audio WHERE identity='unknown'")->fetchColumn()==='retired','Unknown-genre download is cancelled before it starts');ensureg($db->query("SELECT state FROM sf_processing_jobs WHERE id='approved-job'")->fetchColumn()==='queued'&&$db->query("SELECT state FROM sf_processing_jobs WHERE id='running-job'")->fetchColumn()==='running','Allowed and already running jobs remain intact');
